const t={preflight:{intro:{t:0,b:{t:2,i:[{t:3}],s:"एक त्वरित रीड-ओनली जाँच कि प्रिंटर प्रिंट शुरू करने के लिए तैयार है।"}},refresh:{t:0,b:{t:2,i:[{t:3}],s:"फिर से जाँचें"}},checking:{t:0,b:{t:2,i:[{t:3}],s:"जाँच हो रही है..."}},ready:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंट के लिए तैयार"}},notReady:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंट के लिए तैयार नहीं"}},checks:{unreachable:{fail:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंटर तक नहीं पहुँचा जा सका"}}},klippy:{pass:{t:0,b:{t:2,i:[{t:3}],s:"Klipper तैयार है"}},fail:{t:0,b:{t:2,i:[{t:3,v:"Klipper तैयार नहीं है (स्थिति: "},{t:4,k:"state"},{t:3,v:")"}]}}},idle:{pass:{t:0,b:{t:2,i:[{t:3}],s:"कोई प्रिंट नहीं चल रहा"}},fail:{t:0,b:{t:2,i:[{t:3,v:"एक प्रिंट पहले से चल रहा है ("},{t:4,k:"state"},{t:3,v:")"}]}}},homed:{pass:{t:0,b:{t:2,i:[{t:3}],s:"सभी अक्ष होम किए गए हैं"}},fail:{t:0,b:{t:2,i:[{t:3,v:"अक्ष होम नहीं किए गए ("},{t:4,k:"axes"},{t:3,v:"); प्रिंट शुरू होने पर आमतौर पर पहले होमिंग होती है"}]}}}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"गाइड"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंट-पूर्व जाँच गाइड"}},close:{t:0,b:{t:2,i:[{t:3}],s:"बंद करें"}},topics:{overview:{title:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंट-पूर्व जाँच क्या है?"}},body:{t:0,b:{t:2,i:[{t:3}],s:"प्रिंटर शुरू करने के लिए तैयार है या नहीं, इसका रीड-ओनली अवलोकन: यह कभी कुछ हिलाता या बदलता नहीं, बस रिपोर्ट करता है। कठोर अवरोधक फ़ैसले को लाल कर देते हैं; चेतावनियाँ सूचित करती हैं पर रोकती नहीं।"}}},checks:{title:{t:0,b:{t:2,i:[{t:3}],s:"यह क्या जाँचता है"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Klipper तैयार है (बंद या त्रुटि में नहीं), कोई प्रिंट पहले से नहीं चल रहा, और अक्ष होम किए गए हैं या नहीं (सूचनात्मक, क्योंकि प्रिंट शुरू होने पर आमतौर पर पहले होमिंग होती है)।"}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"शब्दावली"}}}},glossary:{klippyState:{term:{t:0,b:{t:2,i:[{t:3}],s:"Klipper स्थिति"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Klipper की अपनी स्थिति - 'ready' का अर्थ है यह कनेक्टेड और निष्क्रिय है; 'shutdown' या 'error' का अर्थ है यह तब तक प्रिंट नहीं कर सकता जब तक इसे साफ़ न किया जाए।"}}},homing:{term:{t:0,b:{t:2,i:[{t:3}],s:"होमिंग"}},def:{t:0,b:{t:2,i:[{t:3}],s:"हर अक्ष को उसके endstop तक ले जाना ताकि प्रिंटर को पता चले कि toolhead कहाँ है। अधिकांश प्रिंट-शुरुआत रूटीन स्वचालित रूप से होमिंग करते हैं।"}}}}}}};export{t as default};
